  "CHIN 1001": {"name": "Elementary Chinese I", "hours": 4, "description": "Intro to Chinese language and pinyin."},
  "CHIN 1002": {"name": "Elementary Chinese II", "hours": 4, "description": "Elementary Chinese language grammar and writing."},
