  "COMPUTING": {"name": "Computing Choice", "hours": 3, "choices": ["CS 1301", "CS 1315", "CS 1371"], "description": "Choose Python, Media Computation, or MATLAB programming."},
  "CS 1100": {"name": "Freshman Leap Seminar", "hours": 1, "description": "Small group discussions with first year students are led by one or more faculty members and include a variety of foundational, motivational, and topical subjects for computationalist."},
  "CS 1171": {"name": "Introductory Computing in MATLAB", "hours": 1, "description": "For students with a solid introductory computing background needing to demonstrate proficiency in the MATLAB language."},
  "CS 1301": {"name": "Introduction to Computing", "hours": 3, "description": "Introduction to computing principles and programming practices with an emphasis on the design, construction and implementation of problem solutions use of software tools."},
  "CS 1301R": {"name": "Introduction to Computing for Computer Science Recitation", "hours": 0, "description": "Recitation for CS 1301."},
  "CS 1315": {"name": "Introduction to Media Computation", "hours": 3, "description": "Introduction to computation (algorithmic thinking, data structures, data transformation and processing, and programming) in a media and communication context. Credit not awarded for both CS 4452 and CS 1315."},
  "CS 1315R": {"name": "CS 1315 Recitation", "hours": 0, "description": "Recitation for CS 1315."},
  "CS 1331": {"name": "Introduction to Object Oriented Programming", "hours": 3, "description": "Introduction to techniques and methods of object-oriented programming such an encapsulation, inheritance, and polymorphism. Emphasis on software development and individual programming skills."},
  "CS 1331R": {"name": "CS 1331 Recitation", "hours": 0, "description": "Recitation for CS 1331."},
  "CS 1332": {"name": "Data Structures and Algorithms for Applications", "hours": 3, "description": "Computer data structures and algorithms in the context of object-oriented programming. Focus on software development towards applications."},
  "CS 1332R": {"name": "CS 1332 Recitation", "hours": 0, "description": "Recitation for CS 1332."},
  "CS 1371": {"name": "Computing for Engineers", "hours": 3, "description": "Foundations of computing with an introduction to design and analysis of algorithms and an introduction to design and construction of programs for engineering problem-solving."},
  "CS 1371R": {"name": "CS 1371 Recitation", "hours": 0, "description": "Recitation for CS 1371."},
