  "MATH 8305": {"name": "Aural-Oral English Skills for Math ESL International Teaching Assistants", "hours": 2, "description": "Enhancement of English listening/speaking skills for SOM international graduate students, post-docs, and new faculty who speak English as their second language (ESL) and who will be teaching undergraduate students."},
  "MATH 8306": {"name": "Academic Communication for Intermediate ESL Math International Teaching Assistants", "hours": 2, "description": "Continued enhancement of English listening/speaking skills for current and future SOM graduate international teaching assistants and international lead instructors who speak English as their second language (ESL)."},
